# round 10: validation of the level equations generated by sk3_exact.py (chart A): for random rational parameter values, the y-coefficients
# from famtool (coeffs_wrt) must reproduce F(J' + sum y_k B_k) - 120 computed independently (numpy F45) at random y.
import sys; sys.path.insert(0,'/home/kevxhk/work/L-gct-210/reg2/gb'); sys.path.insert(0,'/home/kevxhk/work/L-gct-210/reg2')
import numpy as np, random
sys.argv=['x','A']; src=open('/home/kevxhk/work/L-gct-210/reg2/sk3_exact.py').read(); exec(src[:src.index('F=Family(params,bfn,6)')])
from famtool import *
from ext6 import F45
F=Family(params,bfn,6)
R=F.R; ys=F.ys
# rebuild lev with keys
A=F.A; cof={}
for i in range(5):
    for j in range(5): cof[(i,j)]=perm4([[A[a][b] for b in range(5) if b!=j] for a in range(5) if a!=i])
lev=R.const(-120)
for j in range(5): lev=add(lev,cof[(4,j)])
rng=random.Random(3); vals={n:rng.randint(-5,5) for n in R.names}
def ev(q): return sum(v*np.prod([vals[R.names[i]]**e for i,e in enumerate(k)]) for k,v in q.items())
Rb=Ring(params); Vb=lambda n: Rb.var(n)
Bs=bfn(Rb,Vb)
def evb(q): return sum(v*np.prod([vals[Rb.names[i]]**e for i,e in enumerate(k)]) for k,v in q.items()) if q else 0
Bn=np.array([[[evb(B[i][j]) for j in range(5)] for i in range(4)] for B in Bs],dtype=float)
Y=sum(vals[ys[k]]*Bn[k] for k in range(6))
print('famtool level polynomial at the point:',ev(lev),'   numpy F45(J+Y)-120:',F45(Y[None])[0]-120)
